import express from 'express';
import { Worker, isMainThread, parentPort, workerData } from 'worker_threads';
import { createHash } from 'crypto';
import { promisify } from 'util';

const app = express();
app.use(express.json({ limit: '1mb' }));

interface JobPayload {
  taskId: string;
  depth: number;
  segments: string[];
  checksum: string;
}

const MAX_QUEUE_SIZE = 100;
const jobQueue: JobPayload[] = [];

function computeChecksum(segments: string[], depth: number): string {
  const raw = segments.join(':') + ':' + depth.toString();
  return createHash('sha256').update(raw).digest('hex').slice(0, 16);
}

function validatePayload(payload: any): payload is JobPayload {
  if (!payload || typeof payload !== 'object') return false;
  if (typeof payload.taskId !== 'string') return false;
  if (typeof payload.depth !== 'number') return false;
  if (!Array.isArray(payload.segments)) return false;
  if (typeof payload.checksum !== 'string') return false;
  if (payload.segments.length > 64) return false;
  if (payload.depth < 0 || payload.depth > 2048) return false;
  const expected = computeChecksum(payload.segments, payload.depth);
  if (payload.checksum !== expected) return false;
  return true;
}

function processSegmentTree(segments: string[], depth: number): string {
  // Iterative segment aggregation - uses heap-allocated queue
  let current = [...segments];
  let remainingDepth = Math.min(depth, 20);

  while (remainingDepth > 0 && current.length > 1) {
    const next: string[] = [];
    for (let i = 0; i < current.length; i += 2) {
      if (i + 1 < current.length) {
        const combined = createHash('sha256')
          .update(current[i])
          .update(current[i + 1])
          .digest('hex');
        next.push(combined);
      } else {
        next.push(current[i]);
      }
    }
    current = next;
    remainingDepth--;
  }

  return current.join('');
}

function executeJob(job: JobPayload): string {
  // Stack-safe computation with bounded iteration
  // The depth parameter is clamped to prevent excessive computation
  const result = processSegmentTree(job.segments, job.depth);
  return result;
}

if (isMainThread) {
  // Proxy trust configuration for X-Forwarded-For
  app.set('trust proxy', 1);

  // Rate limiting state per IP
  const rateLimits = new Map<string, { count: number; resetAt: number }>();

  // Periodically prune expired rate-limit entries to prevent unbounded growth
  const RATE_LIMIT_PRUNE_INTERVAL = 60000;
  const pruneTimer = setInterval(() => {
    const now = Date.now();
    for (const [ip, entry] of rateLimits) {
      if (now > entry.resetAt) {
        rateLimits.delete(ip);
      }
    }
  }, RATE_LIMIT_PRUNE_INTERVAL);
  // Do not keep the event loop alive solely for pruning
  if (typeof pruneTimer.unref === 'function') {
    pruneTimer.unref();
  }

  function checkRateLimit(ip: string): boolean {
    const now = Date.now();
    const entry = rateLimits.get(ip);
    if (!entry || now > entry.resetAt) {
      rateLimits.set(ip, { count: 1, resetAt: now + 60000 });
      return true;
    }
    if (entry.count >= 10) return false;
    entry.count++;
    return true;
  }

  // Bound the maximum time a worker may run before it is forcibly terminated
  const WORKER_TIMEOUT_MS = 5000;

  app.post('/api/jobs', (req, res) => {
    const clientIp = req.ip || '0.0.0.0';
    if (!checkRateLimit(clientIp)) {
      return res.status(429).json({ error: 'Rate limited' });
    }

    if (!validatePayload(req.body)) {
      return res.status(400).json({ error: 'Invalid payload' });
    }

    if (jobQueue.length >= MAX_QUEUE_SIZE) {
      return res.status(503).json({ error: 'Queue full' });
    }

    const job = req.body as JobPayload;
    jobQueue.push(job);

    // Helper to remove this job from the queue once it is handled so the
    // queue does not grow unbounded and permanently block new work.
    let dequeued = false;
    const dequeue = () => {
      if (dequeued) return;
      dequeued = true;
      const idx = jobQueue.indexOf(job);
      if (idx !== -1) {
        jobQueue.splice(idx, 1);
      }
    };

    // Guard against sending a response more than once.
    let responded = false;
    const respond = (fn: () => void) => {
      if (responded) return;
      responded = true;
      fn();
    };

    // Process in worker thread with constrained resources
    const worker = new Worker(__filename, {
      workerData: job,
      resourceLimits: {
        maxOldGenerationSizeMb: 64,
        maxYoungGenerationSizeMb: 16,
        stackSizeMb: 2
      }
    });

    // Enforce an execution timeout so hung workers are cleaned up.
    const timeout = setTimeout(() => {
      worker.terminate();
      dequeue();
      respond(() => res.status(504).json({ error: 'Processing timed out' }));
    }, WORKER_TIMEOUT_MS);
    if (typeof timeout.unref === 'function') {
      timeout.unref();
    }

    const cleanup = () => {
      clearTimeout(timeout);
      dequeue();
      worker.terminate();
    };

    worker.on('message', (result) => {
      cleanup();
      respond(() => res.json({ taskId: job.taskId, result }));
    });

    worker.on('error', (err) => {
      cleanup();
      respond(() => res.status(500).json({ error: 'Processing failed' }));
    });

    worker.on('exit', () => {
      // Ensure resources are released and the queue slot is freed even if
      // the worker exits without emitting a message or error.
      clearTimeout(timeout);
      dequeue();
      respond(() => res.status(500).json({ error: 'Processing failed' }));
    });
  });

  app.listen(3000, '127.0.0.1');
} else {
  // Worker thread execution
  const job = workerData as JobPayload;
  const result = executeJob(job);
  parentPort?.postMessage(result);
}
